def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    - Recurses only where BOTH values are dictionaries.
    - Treats lists (and all other non-dict values) atomically.
    - If an entire dictionary key is added/removed, returns that parent path only.
    - String keys never contain dots.
    """
    results = []
    _compare(before, after, "", results)
    return sorted(results)


def _compare(before, after, prefix, results):
    for key in before:
        path = f"{prefix}.{key}" if prefix else key
        if key not in after:
            results.append(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _compare(b_val, a_val, path, results)
            else:
                if b_val != a_val:
                    results.append(path)

    for key in after:
        if key not in before:
            path = f"{prefix}.{key}" if prefix else key
            results.append(path)
