def frames(lines):
    events = []
    data_fields = []

    for line in lines:
        if line == "":
            if data_fields:
                events.append("\n".join(data_fields))
            data_fields = []
        elif line.startswith(":"):
            continue
        else:
            if ":" in line:
                field, _, value = line.partition(":")
                if value.startswith(" "):
                    value = value[1:]
            else:
                field = line
                value = ""
            if field == "data":
                data_fields.append(value)

    return events
