from bisect import bisect_right

def histogram(edges, values):
    if not isinstance(edges, (list, tuple)) or len(edges) < 2:
        raise ValueError("edges must be a list with at least two elements")
    for i in range(len(edges) - 1):
        if not edges[i] < edges[i + 1]:
            raise ValueError("edges must be strictly increasing")

    n_bins = len(edges) - 1
    counts = [0] * n_bins

    for v in values:
        if v < edges[0] or v > edges[-1]:
            continue
        idx = bisect_right(edges, v)
        bin_index = min(idx - 1, n_bins - 1)
        counts[bin_index] += 1

    return counts
```

