def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries into a deep-independent result.

    - Overlay values replace base values (including lists and None).
    - A None value in overlay does not delete a key; it replaces the base value.
    - Nested dicts are merged recursively; all other types are replaced wholesale.
    - Inputs are never mutated or aliased in the result.
    """
    result = {}
    for key in base:
        if key in overlay:
            base_val = base[key]
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = _deep_copy(overlay_val)
        else:
            result[key] = _deep_copy(base[key])
    for key in overlay:
        if key not in base:
            result[key] = _deep_copy(overlay[key])
    return result


def _deep_copy(value):
    """Return a deep copy of a JSON-like value (dict, list, or immutable scalar)."""
    if isinstance(value, dict):
        return {k: _deep_copy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_copy(v) for v in value]
    return value  # str, int, float, bool, None are immutable
```

