def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    result = []
    current_batch = []
    current_sum = 0

    for item in items:
        item_len = len(item.encode("utf-8"))
        if item_len > max_bytes:
            raise ValueError(f"Item exceeds max_bytes: {item!r}")

        if current_sum + item_len <= max_bytes:
            current_batch.append(item)
            current_sum += item_len
        else:
            result.append(current_batch)
            current_batch = [item]
            current_sum = item_len

    if current_batch:
        result.append(current_batch)

    return result
