import heapq


def order(deps):
    # Collect all nodes (keys and prerequisite-only nodes)
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    # Build in-degree counts and reverse adjacency (dependents)
    prereq_count = {node: 0 for node in all_nodes}
    dependents = {node: [] for node in all_nodes}

    for node, prereqs in deps.items():
        for p in set(prereqs):
            prereq_count[node] += 1
            dependents[p].append(node)

    # Initialize min-heap with all nodes that have no prerequisites
    heap = [node for node in all_nodes if prereq_count[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            prereq_count[dependent] -= 1
            if prereq_count[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
