def redact(value, sensitive):
    sensitive_set = {s.lower() for s in sensitive}
    return _redact(value, sensitive_set)


def _redact(value, sensitive_set):
    if isinstance(value, dict):
        result = {}
        for key, val in value.items():
            if key.lower() in sensitive_set:
                result[key] = "[REDACTED]"
            else:
                result[key] = _redact(val, sensitive_set)
        return result
    elif isinstance(value, list):
        return [_redact(item, sensitive_set) for item in value]
    else:
        return value
